// Import Axios (browser-ready build for Webpack 5)
import axios from "axios/dist/browser/axios.cjs";

// API base URL from .env
const API_BASE = process.env.REACT_APP_API_URL;

// Create Axios instance
const API = axios.create({
  baseURL: API_BASE,
  timeout: 10000,
  headers: {
    "Content-Type": "application/json",
  },
});

// Optional: Response interceptor for logging errors
API.interceptors.response.use(
  (response) => response,
  (error) => {
    console.error("API Error:", error?.response || error.message);
    return Promise.reject(error);
  }
);

// ------------------ API FUNCTIONS ------------------

// Fetch all incidents with optional filters and pagination
export const fetchIncidents = (params) => API.get("/incidents", { params });

// Fetch a single incident by ID
export const fetchIncidentById = (id) => API.get(`/incidents/${id}`);

// Create a new incident
export const createIncident = (data) => API.post("/incidents", data);

// Update incident status (Open, In Progress, Closed)
export const updateIncidentStatus = (id, status) =>
  API.patch(`/incidents/${id}/status`, { status });

// Add a comment to an incident
export const addIncidentComment = (id, text) =>
  API.post(`/incidents/${id}/comments`, { text });
